"use client";

import { Metadata } from "next";
import ServerError from "~/page/Errors/ServerError";
import { createMeta } from "~/utils/meta";

export const metadata: Metadata = createMeta({
  title: "Something Went Wrong | Pinktra",
  description: "An unexpected error occurred while loading this page. Please try again later.",

  type: "website",
  robots: "noindex,nofollow",
  keywords: "error, application error, pinktra",
});

export default function ErrorBoundary({ error }: { error: Error & { digest?: string } }) {
  return <ServerError error={error} />;
}
