import ErrorLayout from "./ErrorLayout";

type Props = {
  error?: unknown;
};

const ServerError = ({ error }: Props) => {
  return (
    <ErrorLayout
      code="500"
      title="Unexpected Error"
      description="Something went wrong while loading this page. Please try again later or return to the Pinktra home page."
      illustration="⚠️"
      showHome
    >
      {process.env.NODE_ENV !== "production" && error instanceof Error && (
        <pre
          style={{
            textAlign: "left",
            marginTop: "1.5rem",
            maxWidth: "900px",
            overflow: "auto",
          }}
        >
          <code>{error.stack}</code>
        </pre>
      )}
    </ErrorLayout>
  );
};

export default ServerError;
